insert into public.skills
  (id, slug, title, description, kind, depth, is_root, epistemic_status, half_life_years, mastery_threshold, sources, curriculum_order)
values
('10000000-0000-4000-8000-000000000000', 'math-1', 'Maîtriser les nombres relatifs et leurs opérations', 'Niveau collège 5e. Additionner, soustraire, multiplier et diviser des nombres relatifs, gérer les règles de signes et les priorités opératoires. Maîtrisé quand l''élève calcule sans erreur une expression numérique mêlant relatifs, parenthèses et priorités, et interprète un relatif dans un contexte concret (température, altitude, solde).', 'savoir-faire', 4, false, 'etabli', NULL, 0.95, '{}', 101),
('10000000-0000-4000-8000-000000000001', 'math-2', 'Utiliser la proportionnalité et les pourcentages', 'Niveau collège 4e. Reconnaître une situation de proportionnalité, appliquer produit en croix, coefficient, échelles, vitesses et pourcentages (hausses/baisses). Maîtrisé quand l''élève distingue proportionnel et non proportionnel, enchaîne des pourcentages successifs et résout un problème concret de partage ou de conversion.', 'savoir-faire', 5, false, 'etabli', NULL, 0.95, '{}', 111),
('10000000-0000-4000-8000-000000000002', 'math-3', 'Développer, factoriser et réduire une expression littérale', 'Niveau collège 4e. Manipuler le calcul littéral : distributivité simple et double, réduction, factorisation par facteur commun, substitution numérique. Maîtrisé quand l''élève développe et factorise correctement des expressions du premier degré et prouve une propriété numérique générale (parité, multiple) par le calcul littéral.', 'savoir-faire', 6, false, 'etabli', NULL, 0.95, '{}', 121),
('10000000-0000-4000-8000-000000000003', 'math-4', 'Résoudre équations et inéquations du premier degré', 'Niveau collège 3e. Résoudre ax+b=cx+d et des inéquations du premier degré, mettre un problème en équation et interpréter la solution. Maîtrisé quand l''élève modélise un problème concret par une équation ou inéquation, la résout rigoureusement et valide la solution dans le contexte.', 'savoir-faire', 7, false, 'etabli', NULL, 0.95, '{}', 131),
('10000000-0000-4000-8000-000000000004', 'math-5', 'Appliquer Pythagore et Thalès', 'Niveau collège 3e. Utiliser le théorème de Pythagore (et sa réciproque) et le théorème de Thalès pour calculer longueurs et prouver perpendicularité, parallélisme ou proportions. Maîtrisé quand l''élève choisit le bon théorème dans une configuration, mène un calcul de longueur multi-étapes et rédige une démonstration correctement justifiée.', 'savoir-faire', 8, false, 'etabli', NULL, 0.95, '{}', 141),
('10000000-0000-4000-8000-000000000005', 'math-6', 'Exploiter statistiques et premières probabilités', 'Niveau collège 3e. Calculer moyenne, médiane, étendue, quartiles, organiser des données, et évaluer une probabilité dans une situation d''équiprobabilité. Maîtrisé quand l''élève interprète des indicateurs statistiques pour comparer deux séries et calcule une probabilité simple à une ou deux épreuves.', 'savoir-faire', 9, false, 'etabli', NULL, 0.95, '{}', 151),
('10000000-0000-4000-8000-000000000006', 'math-7', 'Étudier une fonction affine ou linéaire et sa représentation', 'Niveau lycée 2de. Manipuler fonctions affines/linéaires, lire graphiquement image et antécédent, déterminer coefficient directeur et ordonnée à l''origine, résoudre équations et inéquations graphiquement. Maîtrisé quand l''élève passe entre expression, tableau et graphique, et modélise un problème par une fonction affine avec interprétation des paramètres.', 'savoir-faire', 10, false, 'etabli', NULL, 0.95, '{}', 161),
('10000000-0000-4000-8000-000000000007', 'math-8', 'Résoudre une équation du second degré', 'Niveau lycée 1re. Résoudre ax²+bx+c=0 par discriminant, factorisation et forme canonique, étudier le signe du trinôme. Maîtrisé quand l''élève discute le nombre de solutions selon le signe du discriminant, dresse le tableau de signes du trinôme et modélise un problème d''optimisation par une fonction du second degré.', 'savoir-faire', 11, false, 'etabli', NULL, 0.95, '{}', 171),
('10000000-0000-4000-8000-000000000008', 'math-9', 'Dériver une fonction et étudier ses variations', 'Niveau lycée Tle. Calculer la dérivée (opérations, composée), déterminer le signe de la dérivée et en déduire variations, extremums et tangentes. Maîtrisé quand l''élève étudie complètement une fonction (dérivée, tableau de variations, tangente) et résout un problème d''optimisation en justifiant l''existence d''un extremum.', 'savoir-faire', 12, false, 'etabli', NULL, 0.95, '{}', 181),
('10000000-0000-4000-8000-000000000009', 'math-10', 'Manipuler suites numériques, limites et récurrence', 'Niveau lycée Tle. Étudier suites arithmétiques, géométriques et définies par récurrence, conjecturer et prouver par récurrence, déterminer une limite. Maîtrisé quand l''élève démontre une propriété par récurrence, détermine le sens de variation et la limite d''une suite, et modélise un phénomène discret (évolution, capital).', 'savoir-faire', 13, false, 'etabli', NULL, 0.95, '{}', 191),
('10000000-0000-4000-8000-000000000010', 'math-11', 'Maîtriser exponentielle et logarithme', 'Niveau lycée Tle. Utiliser les fonctions exp et ln, leurs propriétés algébriques, limites, dérivées et équations associées. Maîtrisé quand l''élève résout équations et inéquations mêlant exp/ln, étudie une fonction en contenant, et modélise croissance ou décroissance exponentielle (radioactivité, population, intérêts).', 'savoir-faire', 14, false, 'etabli', NULL, 0.95, '{}', 201),
('10000000-0000-4000-8000-000000000011', 'math-12', 'Calculer avec vecteurs, trigonométrie et probabilités conditionnelles', 'Niveau lycée Tle. Manipuler vecteurs et repérage, cercle trigonométrique et fonctions trigonométriques, probabilités conditionnelles, indépendance et loi binomiale. Maîtrisé quand l''élève résout un problème de géométrie vectorielle, exploite un arbre pondéré et la formule des probabilités totales, et calcule une probabilité binomiale contextualisée.', 'savoir-faire', 15, false, 'etabli', NULL, 0.95, '{}', 211),
('10000000-0000-4000-8000-000000000012', 'math-13', 'Fonder l''analyse réelle : suites, limites et continuité', 'Niveau licence L1. Maîtriser la construction de R, bornes sup/inf, définition en epsilon des limites, continuité et théorème des valeurs intermédiaires. Maîtrisé quand l''étudiant rédige une preuve rigoureuse en epsilon-delta, démontre convergence ou divergence d''une suite et exploite les grands théorèmes (Bolzano-Weierstrass, valeurs intermédiaires).', 'savoir-faire', 16, false, 'etabli', NULL, 0.95, '{}', 221),
('10000000-0000-4000-8000-000000000013', 'math-14', 'Maîtriser calcul différentiel et intégral d''une variable', 'Niveau licence L1. Dérivabilité, théorème des accroissements finis, développements limités, intégrale de Riemann et théorème fondamental de l''analyse. Maîtrisé quand l''étudiant justifie l''intégrabilité d''une fonction, calcule via développements limités et théorèmes fins, et démontre une inégalité par les accroissements finis ou la convexité.', 'savoir-faire', 17, false, 'etabli', NULL, 0.95, '{}', 231),
('10000000-0000-4000-8000-000000000014', 'math-15', 'Structurer l''algèbre linéaire : espaces vectoriels et applications', 'Niveau licence L1. Espaces vectoriels, bases, dimension, applications linéaires, matrices, rang, systèmes linéaires. Maîtrisé quand l''étudiant démontre qu''un ensemble est un sous-espace, détermine noyau, image et rang d''une application, et relie représentation matricielle et changement de base.', 'savoir-faire', 18, false, 'etabli', NULL, 0.95, '{}', 241),
('10000000-0000-4000-8000-000000000015', 'math-16', 'Réduire les endomorphismes : diagonalisation et spectre', 'Niveau licence L2. Déterminants, valeurs propres, vecteurs propres, polynôme caractéristique, diagonalisation et trigonalisation. Maîtrisé quand l''étudiant diagonalise ou trigonalise une matrice, utilise le polynôme minimal et Cayley-Hamilton, et applique la réduction au calcul de puissances ou à des systèmes différentiels.', 'savoir-faire', 19, false, 'etabli', NULL, 0.95, '{}', 251),
('10000000-0000-4000-8000-000000000016', 'math-17', 'Analyser fonctions de plusieurs variables et séries', 'Niveau licence L2. Calcul différentiel en plusieurs variables (gradient, jacobienne, extrema liés), séries numériques et séries de fonctions, convergence uniforme, séries entières. Maîtrisé quand l''étudiant étudie la nature d''une série, justifie une interversion limite-intégrale par convergence uniforme et détermine les extrema d''une fonction de plusieurs variables sous contrainte.', 'savoir-faire', 20, false, 'etabli', NULL, 0.95, '{}', 261),
('10000000-0000-4000-8000-000000000017', 'math-18', 'Construire l''algèbre générale : groupes, anneaux, corps', 'Niveau licence L2. Structures algébriques, morphismes, sous-groupes distingués, quotients, arithmétique des anneaux, corps finis. Maîtrisé quand l''étudiant démontre un isomorphisme via le théorème de factorisation, manipule groupes quotients et idéaux, et applique la théorie à l''arithmétique (Z/nZ, corps finis).', 'savoir-faire', 21, false, 'etabli', NULL, 0.95, '{}', 271),
('10000000-0000-4000-8000-000000000018', 'math-19', 'Maîtriser topologie et espaces métriques', 'Niveau licence L3. Espaces topologiques et métriques, ouverts, compacité, connexité, complétude, continuité et convergence dans les espaces normés. Maîtrisé quand l''étudiant démontre compacité ou complétude d''un espace, exploite les théorèmes de point fixe et caractérise la continuité par les images réciproques d''ouverts.', 'savoir-faire', 22, false, 'etabli', NULL, 0.95, '{}', 281),
('10000000-0000-4000-8000-000000000019', 'math-20', 'Fonder théorie de la mesure et intégrale de Lebesgue', 'Niveau licence L3. Tribus, mesures, fonctions mesurables, intégrale de Lebesgue, théorèmes de convergence (monotone, dominée), théorème de Fubini. Maîtrisé quand l''étudiant justifie une interversion limite-intégrale par convergence dominée, construit des espaces Lp et applique Fubini-Tonelli au calcul d''intégrales multiples.', 'savoir-faire', 23, false, 'etabli', NULL, 0.95, '{}', 291),
('10000000-0000-4000-8000-000000000020', 'math-21', 'Développer probabilités fondées sur la mesure', 'Niveau licence L3. Espaces probabilisés, variables aléatoires, espérance comme intégrale, lois usuelles, indépendance, lois des grands nombres et théorème central limite. Maîtrisé quand l''étudiant démontre une convergence en loi ou presque sûre, manipule fonctions caractéristiques et prouve rigoureusement une version du théorème central limite.', 'savoir-faire', 24, false, 'etabli', NULL, 0.95, '{}', 301),
('10000000-0000-4000-8000-000000000021', 'math-22', 'Maîtriser l''analyse fonctionnelle : espaces de Banach et Hilbert', 'Niveau master M1. Espaces de Banach et Hilbert, opérateurs bornés, dualité, théorèmes de Hahn-Banach, Banach-Steinhaus, graphe fermé, bases hilbertiennes et théorie spectrale. Maîtrisé quand l''étudiant applique les grands théorèmes à un problème d''existence, exploite la dualité faible et décompose un opérateur compact auto-adjoint par son spectre.', 'savoir-faire', 25, false, 'etabli', NULL, 0.95, '{}', 311),
('10000000-0000-4000-8000-000000000022', 'math-23', 'Étudier géométrie différentielle : variétés et formes', 'Niveau master M1. Variétés différentielles, espaces tangents, champs de vecteurs, formes différentielles, dérivée extérieure, orientation et théorème de Stokes. Maîtrisé quand l''étudiant travaille en cartes et changements de cartes, calcule sur les formes différentielles et démontre ou applique le théorème de Stokes sur une variété à bord.', 'savoir-faire', 26, false, 'etabli', NULL, 0.95, '{}', 321),
('10000000-0000-4000-8000-000000000023', 'math-24', 'Analyser processus stochastiques et calcul d''Itô', 'Niveau master M1. Martingales, chaînes de Markov, mouvement brownien, intégrale stochastique, formule d''Itô et équations différentielles stochastiques. Maîtrisé quand l''étudiant démontre une propriété de martingale, applique la formule d''Itô pour résoudre une EDS et modélise un phénomène aléatoire continu (finance, diffusion) avec rigueur.', 'savoir-faire', 27, false, 'etabli', NULL, 0.95, '{}', 331),
('10000000-0000-4000-8000-000000000024', 'math-25', 'Approfondir un domaine avancé : EDP, géométrie ou algèbre', 'Niveau master M2. Théories spécialisées (EDP et espaces de Sobolev, géométrie riemannienne, cohomologie, ou théorie analytique des nombres) au niveau des articles fondateurs. Maîtrisé quand l''étudiant lit et restitue un article de recherche récent, reproduit ses démonstrations clés et identifie ses hypothèses, limites et prolongements ouverts.', 'savoir-faire', 28, false, 'etabli', NULL, 0.95, '{}', 341),
('10000000-0000-4000-8000-000000000025', 'math-26', 'Mener une recherche originale en mathématiques', 'Niveau doctorat. Produire un résultat nouveau dans un domaine spécialisé (ex. géométrie algébrique, théorie des nombres, analyse harmonique) : conjecture, démonstration complète, insertion dans l''état de l''art. Maîtrisé quand le chercheur démontre un théorème inédit, rédige un article accepté par une revue à comité de lecture et le défend devant la communauté.', 'savoir-faire', 29, false, 'etabli', NULL, 0.95, '{}', 351),
('10000000-0000-4000-8000-000000000026', 'math-27', 'Diriger un programme de recherche et ouvrir des théories', 'Niveau au-delà du doctorat. Formuler des conjectures structurantes, bâtir des outils théoriques nouveaux et fédérer un programme de recherche à l''échelle internationale. Maîtrisé quand le chercheur ouvre un champ ou résout un problème majeur reconnu, essaime des méthodes réutilisées par d''autres et encadre une génération de doctorants et postdocs.', 'savoir-faire', 30, false, 'etabli', NULL, 0.95, '{}', 361),
('20000000-0000-4000-8000-000000000000', 'lettres-1', 'Grammaire et syntaxe avancées', 'Niveau collège 5e-4e. Maîtriser la phrase complexe : subordination, propositions relatives, conjonctives, circonstancielles, concordance des temps, valeurs des modes. Maîtrisé quand l''élève analyse la fonction de chaque proposition d''un texte donné et produit sans faute des phrases complexes variées et grammaticalement justes.', 'savoir-faire', 4, false, 'etabli', NULL, 0.95, '{}', 102),
('20000000-0000-4000-8000-000000000001', 'lettres-2', 'Lexique, étymologie et niveaux de langue', 'Niveau collège 4e. Enrichir et nuancer le vocabulaire : champs lexicaux, connotation, registres (familier, courant, soutenu), racines gréco-latines. Maîtrisé quand l''élève identifie le registre d''un texte, justifie l''effet d''un choix lexical et reformule un même contenu dans trois registres distincts.', 'savoir-faire', 5, false, 'etabli', NULL, 0.95, '{}', 112),
('20000000-0000-4000-8000-000000000002', 'lettres-3', 'Analyse d''un texte narratif', 'Niveau collège 4e. Repérer schéma narratif, schéma actanciel, points de vue (focalisations), rythme du récit (sommaire, ellipse, scène, pause). Maîtrisé quand l''élève démonte la construction d''une nouvelle et explique comment la focalisation oriente la lecture, exemples à l''appui.', 'savoir-faire', 6, false, 'etabli', NULL, 0.95, '{}', 122),
('20000000-0000-4000-8000-000000000003', 'lettres-4', 'Figures de style et procédés d''écriture', 'Niveau collège 3e. Identifier et nommer métaphore, métonymie, comparaison, hyperbole, litote, anaphore, gradation, oxymore et leurs effets. Maîtrisé quand l''élève relève les figures d''un poème ou d''une prose, interprète leur fonction dans le sens global et en réemploie à bon escient dans ses propres écrits.', 'savoir-faire', 7, false, 'etabli', NULL, 0.95, '{}', 132),
('20000000-0000-4000-8000-000000000004', 'lettres-5', 'Expression écrite structurée', 'Niveau collège 3e. Rédiger un texte organisé en paragraphes cohérents avec connecteurs logiques, thèse et progression, en respectant un genre imposé (lettre, récit, texte explicatif). Maîtrisé quand l''élève produit un texte de 300-500 mots à la structure claire, cohérence temporelle et logique sans rupture, orthographe et ponctuation maîtrisées.', 'savoir-faire', 8, false, 'etabli', NULL, 0.95, '{}', 142),
('20000000-0000-4000-8000-000000000005', 'lettres-6', 'Argumentation écrite structurée', 'Niveau collège 3e. Construire un raisonnement argumenté : thèse, arguments hiérarchisés, exemples, réfutation, concession. Maîtrisé quand l''élève défend une position dans un texte structuré qui anticipe et réfute une objection, en distinguant argument et exemple.', 'savoir-faire', 9, false, 'etabli', NULL, 0.95, '{}', 152),
('20000000-0000-4000-8000-000000000006', 'lettres-7', 'Étude d''une œuvre intégrale', 'Niveau collège 3e. Lire une œuvre complète (roman, pièce, recueil) et l''analyser : personnages, thèmes, contexte, enjeux, genre. Maîtrisé quand l''élève rend compte d''une œuvre intégrale par un écrit personnel qui articule interprétation argumentée et références précises au texte.', 'savoir-faire', 10, false, 'etabli', NULL, 0.95, '{}', 162),
('20000000-0000-4000-8000-000000000007', 'lettres-8', 'Lecture analytique et explication de texte', 'Niveau lycée 2de. Conduire une lecture linéaire ou analytique : dégager un projet de lecture, analyser mouvements, procédés et effets pour construire une interprétation. Maîtrisé quand l''élève propose à l''oral et à l''écrit une explication ordonnée d''un extrait inconnu, reliant chaque observation formelle à un enjeu de sens.', 'savoir-faire', 11, false, 'etabli', NULL, 0.95, '{}', 172),
('20000000-0000-4000-8000-000000000008', 'lettres-9', 'Le commentaire composé', 'Niveau lycée 1re. Rédiger un commentaire organisé en axes de lecture problématisés, sans paraphrase, mêlant analyse formelle et interprétation. Maîtrisé quand l''élève compose sur un texte inconnu un devoir en deux ou trois axes cohérents, chaque sous-partie articulant procédé, citation et interprétation.', 'savoir-faire', 12, false, 'etabli', NULL, 0.95, '{}', 182),
('20000000-0000-4000-8000-000000000009', 'lettres-10', 'La dissertation littéraire', 'Niveau lycée 1re-Tle. Traiter un sujet de réflexion sur la littérature : analyse du libellé, problématique, plan dialectique ou thématique, exemples issus des œuvres. Maîtrisé quand l''élève construit une dissertation problématisée dont chaque partie répond au sujet et s''appuie sur des références littéraires précises et pertinentes.', 'savoir-faire', 13, false, 'etabli', NULL, 0.95, '{}', 192),
('20000000-0000-4000-8000-000000000010', 'lettres-11', 'Mouvements littéraires et histoire des formes', 'Niveau lycée Tle. Situer et caractériser les grands mouvements (humanisme, baroque, classicisme, Lumières, romantisme, réalisme, symbolisme, surréalisme) et leurs enjeux esthétiques. Maîtrisé quand l''élève rattache une œuvre à son mouvement en justifiant par des traits formels et idéologiques, et compare deux esthétiques sur un même thème.', 'savoir-faire', 14, false, 'etabli', NULL, 0.95, '{}', 202),
('20000000-0000-4000-8000-000000000011', 'lettres-12', 'Analyse stylistique', 'Niveau lycée Tle. Décrire précisément la langue d''un texte : lexique, syntaxe, rythme, sonorités, énonciation, tonalités, et lier ces faits de style à un effet. Maîtrisé quand l''élève produit une analyse stylistique rigoureuse d''un passage, en nommant les faits de langue avec le métalangage exact et en démontrant leur portée.', 'savoir-faire', 15, false, 'etabli', NULL, 0.95, '{}', 212),
('20000000-0000-4000-8000-000000000012', 'lettres-13', 'Rhétorique et art de convaincre', 'Niveau lycée Tle / licence L1. Maîtriser les ressorts de l''éloquence : inventio, dispositio, elocutio, ethos, pathos, logos, sophismes. Maîtrisé quand l''étudiant analyse la stratégie persuasive d''un discours et compose un texte argumentatif dont il justifie chaque choix rhétorique.', 'savoir-faire', 16, false, 'etabli', NULL, 0.95, '{}', 222),
('20000000-0000-4000-8000-000000000013', 'lettres-14', 'Histoire littéraire et périodisation', 'Niveau licence L1-L2. Maîtriser la chronologie littéraire française et francophone, ses ruptures, filiations et contextes socio-historiques. Maîtrisé quand l''étudiant replace une œuvre dans son histoire, discute la notion de période et sait problématiser une périodisation plutôt que la réciter.', 'savoir-faire', 17, false, 'etabli', NULL, 0.95, '{}', 232),
('20000000-0000-4000-8000-000000000014', 'lettres-15', 'Littérature comparée', 'Niveau licence L2-L3. Mettre en relation textes de langues, cultures ou époques différentes : circulation des motifs, genres, influences, traductions. Maîtrisé quand l''étudiant construit une comparaison problématisée entre deux œuvres de traditions distinctes, dépassant le rapprochement pour dégager un enjeu critique.', 'savoir-faire', 18, false, 'etabli', NULL, 0.95, '{}', 242),
('20000000-0000-4000-8000-000000000015', 'lettres-16', 'Théorie littéraire et notions critiques', 'Niveau licence L3. Connaître et mobiliser les grands cadres théoriques : formalisme, structuralisme, narratologie, sémiotique, réception, intertextualité. Maîtrisé quand l''étudiant applique un cadre théorique à un corpus en explicitant ses concepts, et en discute les limites face au texte.', 'savoir-faire', 19, false, 'etabli', NULL, 0.95, '{}', 252),
('20000000-0000-4000-8000-000000000016', 'lettres-17', 'Poétique des genres', 'Niveau licence L3. Analyser les propriétés et l''évolution des genres (roman, poésie, théâtre, essai, formes brèves) et leurs codes. Maîtrisé quand l''étudiant caractérise le fonctionnement générique d''une œuvre, en repère les transgressions et les interprète comme geste esthétique.', 'savoir-faire', 20, false, 'etabli', NULL, 0.95, '{}', 262),
('20000000-0000-4000-8000-000000000017', 'lettres-18', 'Analyse critique et lecture des lectures', 'Niveau licence L3. Lire, situer et évaluer la critique existante sur une œuvre : identifier thèses, présupposés méthodologiques et débats. Maîtrisé quand l''étudiant confronte plusieurs lectures critiques divergentes d''un même texte et prend position argumentée dans le débat.', 'savoir-faire', 21, false, 'etabli', NULL, 0.95, '{}', 272),
('20000000-0000-4000-8000-000000000018', 'lettres-19', 'Méthodologie de la recherche en lettres', 'Niveau master M1. Construire un objet de recherche : problématique, état de l''art, corpus, cadre théorique, bibliographie, appareil de citation. Maîtrisé quand l''étudiant rédige un projet de recherche cohérent dont la problématique est neuve, le corpus justifié et l''état de l''art critique et à jour.', 'savoir-faire', 22, false, 'etabli', NULL, 0.95, '{}', 282),
('20000000-0000-4000-8000-000000000019', 'lettres-20', 'Critique littéraire avancée et interprétation', 'Niveau master M1-M2. Produire une interprétation soutenue d''une œuvre en mobilisant théorie, contexte et analyse serrée du texte. Maîtrisé quand l''étudiant rédige un mémoire d''analyse dont la thèse est démontrée pas à pas, résiste aux objections et apporte une lecture qui ne se réduit pas à l''état de l''art.', 'savoir-faire', 23, false, 'etabli', NULL, 0.95, '{}', 292),
('20000000-0000-4000-8000-000000000020', 'lettres-21', 'Édition critique et génétique textuelle', 'Niveau master M2. Établir un texte : philologie, variantes, manuscrits, apparat critique, annotation, histoire de la transmission. Maîtrisé quand l''étudiant produit l''édition critique annotée d''un fragment, justifie ses choix d''établissement du texte et rend compte du dossier génétique.', 'savoir-faire', 24, false, 'etabli', NULL, 0.95, '{}', 302),
('20000000-0000-4000-8000-000000000021', 'lettres-22', 'Théorie critique de pointe et herméneutique', 'Niveau master M2 / doctorat. Maîtriser les courants critiques contemporains (déconstruction, études postcoloniales, de genre, écopoétique, cognitives, humanités numériques) et les traditions herméneutiques. Maîtrisé quand le chercheur mobilise ces cadres de façon critique et réflexive, en interroge les fondements épistémologiques et les met en tension productive.', 'savoir-faire', 25, false, 'etabli', NULL, 0.95, '{}', 312),
('20000000-0000-4000-8000-000000000022', 'lettres-23', 'Recherche doctorale : thèse originale en lettres', 'Niveau doctorat. Concevoir et mener une recherche inédite : hypothèse originale, corpus maîtrisé, méthode explicitée, contribution au savoir. Maîtrisé quand le doctorant soutient une thèse jugée par un jury comme apport original et défendable à la discipline, cohérente de la problématique aux conclusions.', 'savoir-faire', 26, false, 'etabli', NULL, 0.95, '{}', 322),
('20000000-0000-4000-8000-000000000023', 'lettres-24', 'Analyse littéraire de niveau publication', 'Niveau doctorat et au-delà. Rédiger un article de recherche qui déplace un débat critique : thèse neuve, dialogue avec l''historiographie, démonstration inattaquable. Maîtrisé quand le texte est accepté par une revue à comité de lecture et reconnu par les pairs comme contribution significative.', 'savoir-faire', 27, false, 'etabli', NULL, 0.95, '{}', 332),
('20000000-0000-4000-8000-000000000024', 'lettres-25', 'Direction de recherche et autorité critique', 'Niveau post-doctorat. Fonder un programme de recherche, encadrer des travaux, expertiser, forger des concepts et orienter un champ. Maîtrisé quand le chercheur dirige des thèses, évalue les travaux des pairs, et voit ses propositions théoriques reprises et discutées comme référence.', 'savoir-faire', 28, false, 'etabli', NULL, 0.95, '{}', 342),
('30000000-0000-4000-8000-000000000000', 'pc-1', 'Matière, états et transformations physiques', 'Niveau collège. Distinguer solide/liquide/gaz, changements d''état, masse/volume/masse volumique, mélanges et corps purs, dissolution. Maîtrisé quand l''élève prévoit un changement d''état et calcule une masse volumique à partir de mesures expérimentales.', 'savoir-faire', 4, false, 'etabli', NULL, 0.95, '{}', 103),
('30000000-0000-4000-8000-000000000001', 'pc-2', 'Réactions chimiques et conservation de la masse', 'Niveau collège. Identifier réactifs/produits, écrire et équilibrer une équation simple, reconnaître combustions et transformations, conservation des atomes. Maîtrisé quand l''élève équilibre une équation et justifie la conservation de la masse dans un système fermé.', 'savoir-faire', 5, false, 'etabli', NULL, 0.95, '{}', 113),
('30000000-0000-4000-8000-000000000002', 'pc-3', 'Énergie : formes, transferts et conservation', 'Niveau collège. Énergie cinétique, potentielle, thermique, électrique ; chaînes énergétiques, rendement qualitatif, unités (J, W). Maîtrisé quand l''élève construit une chaîne énergétique complète d''un dispositif et identifie les pertes.', 'savoir-faire', 6, false, 'etabli', NULL, 0.95, '{}', 123),
('30000000-0000-4000-8000-000000000003', 'pc-4', 'Circuits électriques et loi d''Ohm', 'Niveau collège. Montages série/dérivation, courant, tension, résistance, loi d''Ohm U=RI, puissance électrique, sécurité. Maîtrisé quand l''élève prédit tensions et intensités dans un circuit mixte et vérifie par la mesure.', 'savoir-faire', 7, false, 'etabli', NULL, 0.95, '{}', 133),
('30000000-0000-4000-8000-000000000004', 'pc-5', 'Mécanique simple : forces, mouvement et pression', 'Niveau collège. Forces (poids, frottement), vitesse moyenne, équilibre, pression dans les fluides, principe d''Archimède qualitatif. Maîtrisé quand l''élève établit le bilan des forces d''un objet et prévoit s''il flotte ou coule.', 'savoir-faire', 8, false, 'etabli', NULL, 0.95, '{}', 143),
('30000000-0000-4000-8000-000000000005', 'pc-6', 'Mécanique newtonienne et lois de Newton', 'Niveau lycée Tle. Vecteurs force et accélération, trois lois de Newton, mouvements rectiligne/parabolique/circulaire, quantité de mouvement. Maîtrisé quand l''élève résout un projectile 2D avec frottements négligés et exploite la conservation de la quantité de mouvement dans un choc.', 'savoir-faire', 9, false, 'etabli', NULL, 0.95, '{}', 153),
('30000000-0000-4000-8000-000000000006', 'pc-7', 'Énergie mécanique et travail', 'Niveau lycée Tle. Travail d''une force, théorèmes de l''énergie cinétique et mécanique, forces conservatives, puissance. Maîtrisé quand l''élève applique le théorème de l''énergie mécanique à un système avec frottements et quantifie l''énergie dissipée.', 'savoir-faire', 10, false, 'etabli', NULL, 0.95, '{}', 163),
('30000000-0000-4000-8000-000000000007', 'pc-8', 'Ondes mécaniques et lumineuses', 'Niveau lycée Tle. Périodicité, célérité, longueur d''onde, diffraction, interférences, effet Doppler, spectre électromagnétique. Maîtrisé quand l''élève exploite une figure d''interférences ou de diffraction pour remonter à une longueur d''onde.', 'savoir-faire', 11, false, 'etabli', NULL, 0.95, '{}', 173),
('30000000-0000-4000-8000-000000000008', 'pc-9', 'Optique géométrique et instruments', 'Niveau lycée Tle. Réflexion, réfraction (Snell-Descartes), lentilles minces, formation d''images, relation de conjugaison. Maîtrisé quand l''élève construit et calcule l''image d''un objet par une lentille et dimensionne un instrument simple.', 'savoir-faire', 12, false, 'etabli', NULL, 0.95, '{}', 183),
('30000000-0000-4000-8000-000000000009', 'pc-10', 'Thermodynamique macroscopique', 'Niveau lycée Tle. Température, chaleur, capacités thermiques, gaz parfait, premier principe, transferts thermiques. Maîtrisé quand l''élève établit un bilan énergétique complet d''un système thermodynamique et applique le premier principe.', 'savoir-faire', 13, false, 'etabli', NULL, 0.95, '{}', 193),
('30000000-0000-4000-8000-000000000010', 'pc-11', 'Chimie des solutions et équilibres', 'Niveau lycée Tle. Concentrations, pH, acides/bases, réactions acido-basiques, oxydoréduction, titrages, constantes d''équilibre. Maîtrisé quand l''élève exploite un titrage pH-métrique pour déterminer une concentration et discute l''équilibre à l''équivalence.', 'savoir-faire', 14, false, 'etabli', NULL, 0.95, '{}', 203),
('30000000-0000-4000-8000-000000000011', 'pc-12', 'Cinétique chimique et transformations', 'Niveau lycée Tle. Vitesse de réaction, facteurs cinétiques, suivi temporel, temps de demi-réaction, catalyse. Maîtrisé quand l''élève détermine une vitesse et un ordre apparent à partir de données expérimentales de suivi.', 'savoir-faire', 15, false, 'etabli', NULL, 0.95, '{}', 213),
('30000000-0000-4000-8000-000000000012', 'pc-13', 'Électromagnétisme de Maxwell', 'Niveau licence L2. Champs E et B, équations de Maxwell locales et intégrales, propagation des ondes EM, potentiels, énergie électromagnétique. Maîtrisé quand l''étudiant dérive l''équation d''onde depuis Maxwell et résout un problème de champ avec symétries (Gauss/Ampère).', 'savoir-faire', 16, false, 'etabli', NULL, 0.95, '{}', 223),
('30000000-0000-4000-8000-000000000013', 'pc-14', 'Mécanique analytique : Lagrange et Hamilton', 'Niveau licence L2. Coordonnées généralisées, principe de moindre action, équations d''Euler-Lagrange, formalisme hamiltonien, lois de conservation (Noether). Maîtrisé quand l''étudiant établit et résout les équations du mouvement d''un système contraint via lagrangien et hamiltonien.', 'savoir-faire', 17, false, 'etabli', NULL, 0.95, '{}', 233),
('30000000-0000-4000-8000-000000000014', 'pc-15', 'Thermodynamique statistique', 'Niveau licence L2. Ensembles microcanonique/canonique/grand-canonique, fonction de partition, entropie de Boltzmann, distributions de Maxwell-Boltzmann. Maîtrisé quand l''étudiant calcule des grandeurs thermodynamiques d''un système à partir de sa fonction de partition.', 'savoir-faire', 18, false, 'etabli', NULL, 0.95, '{}', 243),
('30000000-0000-4000-8000-000000000015', 'pc-16', 'Mécanique quantique introductive', 'Niveau licence L2. Fonction d''onde, équation de Schrödinger, puits et barrières, oscillateur harmonique, moment cinétique, atome d''hydrogène. Maîtrisé quand l''étudiant résout Schrödinger pour un potentiel 1D et interprète spectre et probabilités de présence.', 'savoir-faire', 19, false, 'etabli', NULL, 0.95, '{}', 253),
('30000000-0000-4000-8000-000000000016', 'pc-17', 'Chimie quantique et liaison', 'Niveau licence L2. Orbitales atomiques et moléculaires, méthode LCAO, hybridation, théorie des groupes appliquée, spectroscopies élémentaires. Maîtrisé quand l''étudiant construit un diagramme d''orbitales moléculaires et en déduit propriétés magnétiques et réactivité.', 'savoir-faire', 20, false, 'etabli', NULL, 0.95, '{}', 263),
('30000000-0000-4000-8000-000000000017', 'pc-18', 'Physique statistique quantique et gaz dégénérés', 'Niveau master. Statistiques de Fermi-Dirac et Bose-Einstein, gaz de fermions, condensation de Bose-Einstein, corps noir. Maîtrisé quand l''étudiant dérive les propriétés d''un gaz d''électrons dégénéré et traite un cas de condensat.', 'savoir-faire', 21, false, 'etabli', NULL, 0.95, '{}', 273),
('30000000-0000-4000-8000-000000000018', 'pc-19', 'Physique de la matière condensée', 'Niveau master. Réseaux cristallins, théorème de Bloch, structures de bandes, phonons, semi-conducteurs, supraconductivité BCS introductive. Maîtrisé quand l''étudiant calcule une structure de bandes en liaisons fortes et interprète les propriétés de transport.', 'savoir-faire', 22, false, 'etabli', NULL, 0.95, '{}', 283),
('30000000-0000-4000-8000-000000000019', 'pc-20', 'Théorie quantique des champs introductive', 'Niveau master. Quantification des champs libres, propagateurs, diagrammes de Feynman, QED à l''arbre, sections efficaces. Maîtrisé quand l''étudiant calcule une amplitude et une section efficace d''un processus QED simple au niveau arbre.', 'savoir-faire', 23, false, 'etabli', NULL, 0.95, '{}', 293),
('30000000-0000-4000-8000-000000000020', 'pc-21', 'Physique des particules et Modèle Standard', 'Niveau master. Symétries de jauge, chromodynamique, interaction électrofaible, mécanisme de Higgs, familles de fermions. Maîtrisé quand l''étudiant classe les interactions d''un processus donné et justifie les règles de sélection et conservations associées.', 'savoir-faire', 24, false, 'etabli', NULL, 0.95, '{}', 303),
('30000000-0000-4000-8000-000000000021', 'pc-22', 'Spectroscopie avancée et méthodes expérimentales', 'Niveau master. RMN, spectroscopies vibrationnelles/électroniques, diffraction, résolution temporelle ultrarapide, traitement du signal. Maîtrisé quand l''étudiant conçoit un protocole spectroscopique et interprète un spectre complexe pour élucider une structure ou une dynamique.', 'savoir-faire', 25, false, 'etabli', NULL, 0.95, '{}', 313),
('30000000-0000-4000-8000-000000000022', 'pc-23', 'Renormalisation et théorie quantique des champs avancée', 'Niveau doctorat. Régularisation, groupe de renormalisation, corrections de boucles, théories de jauge non abéliennes, anomalies. Maîtrisé quand le chercheur mène un calcul à une boucle renormalisé et publie une prédiction confrontable à l''expérience.', 'savoir-faire', 26, false, 'etabli', NULL, 0.95, '{}', 323),
('30000000-0000-4000-8000-000000000023', 'pc-24', 'Cosmologie théorique et relativité générale', 'Niveau doctorat. Équations d''Einstein, modèles FLRW, inflation, perturbations cosmologiques, fond diffus, énergie et matière noires. Maîtrisé quand le chercheur dérive un spectre de perturbations d''un modèle et le contraint sur données observationnelles (CMB, structures).', 'savoir-faire', 27, false, 'etabli', NULL, 0.95, '{}', 333),
('30000000-0000-4000-8000-000000000024', 'pc-25', 'Nanophysique et systèmes quantiques corrélés', 'Niveau doctorat. Transport mésoscopique, effet Hall quantique, systèmes fortement corrélés, matériaux topologiques, information quantique de la matière. Maîtrisé quand le chercheur modélise un système nanométrique original et produit un résultat théorique ou expérimental publiable.', 'savoir-faire', 28, false, 'etabli', NULL, 0.95, '{}', 343),
('30000000-0000-4000-8000-000000000025', 'pc-26', 'Recherche de frontière : conception et publication', 'Niveau doctorat et au-delà. Formuler une problématique ouverte, choisir méthodes théoriques/numériques/expérimentales, quantifier incertitudes, soumettre à comité de lecture. Maîtrisé quand le chercheur publie un résultat original revu par les pairs faisant progresser un domaine de la physique-chimie.', 'savoir-faire', 29, false, 'etabli', NULL, 0.95, '{}', 353),
('40000000-0000-4000-8000-000000000000', 'info-1', 'Pensée computationnelle et résolution de problèmes', 'Niveau collège. Décomposer un problème en sous-étapes, reconnaître des motifs, abstraire et concevoir un algorithme simple (pseudocode, organigramme) indépendamment de la machine. Maîtrisé quand l''élève décompose un problème inédit du quotidien en algorithme non ambigu, exécutable pas à pas par un tiers sans hésitation.', 'savoir-faire', 4, false, 'etabli', NULL, 0.95, '{}', 104),
('40000000-0000-4000-8000-000000000001', 'info-2', 'Logique booléenne et représentation binaire', 'Niveau collège. Manipuler ET/OU/NON, tables de vérité, codage binaire des nombres et caractères, notion de bit et d''octet. Maîtrisé quand l''élève convertit entre binaire/décimal, simplifie une expression booléenne à trois variables et explique comment un ordinateur encode texte et images.', 'savoir-faire', 5, false, 'etabli', NULL, 0.95, '{}', 114),
('40000000-0000-4000-8000-000000000002', 'info-3', 'Premiers programmes : variables, boucles, conditions', 'Niveau collège. Écrire des programmes structurés (Scratch puis Python) avec variables, entrées/sorties, tests et boucles bornées et conditionnelles. Maîtrisé quand l''élève programme seul un jeu ou un utilitaire interactif fonctionnel et corrige ses propres bugs par test méthodique.', 'savoir-faire', 6, false, 'etabli', NULL, 0.95, '{}', 124),
('40000000-0000-4000-8000-000000000003', 'info-4', 'Algorithmique de base : tris, recherches, parcours', 'Niveau collège. Comprendre et coder recherche linéaire/dichotomique, tri par sélection/insertion, et raisonner sur le nombre d''opérations. Maîtrisé quand l''élève implémente ces algorithmes, trace leur exécution et justifie pourquoi la dichotomie bat la recherche linéaire sur données triées.', 'savoir-faire', 7, false, 'etabli', NULL, 0.95, '{}', 134),
('40000000-0000-4000-8000-000000000004', 'info-5', 'Programmation structurée et fonctions', 'Niveau lycée. Concevoir des programmes modulaires avec fonctions, paramètres, portée des variables, gestion d''erreurs et bonnes pratiques de style. Maîtrisé quand l''élève découpe un problème de taille moyenne en fonctions réutilisables testées unitairement, sans code dupliqué.', 'savoir-faire', 8, false, 'etabli', NULL, 0.95, '{}', 144),
('40000000-0000-4000-8000-000000000005', 'info-6', 'Structures de données fondamentales', 'Niveau lycée. Utiliser tableaux, listes, piles, files, dictionnaires et ensembles ; choisir la structure adaptée à un besoin. Maîtrisé quand l''élève sélectionne et justifie la structure optimale pour un problème donné et implémente les opérations de base avec leur coût.', 'savoir-faire', 9, false, 'etabli', NULL, 0.95, '{}', 154),
('40000000-0000-4000-8000-000000000006', 'info-7', 'Récursivité et diviser-pour-régner', 'Niveau lycée. Concevoir des fonctions récursives (cas de base, réduction), comprendre la pile d''appels, résoudre par diviser-pour-régner (tri fusion, tours de Hanoï). Maîtrisé quand l''élève écrit une solution récursive correcte à un problème non trivial et sait la convertir en version itérative.', 'savoir-faire', 10, false, 'etabli', NULL, 0.95, '{}', 164),
('40000000-0000-4000-8000-000000000007', 'info-8', 'Bases de données relationnelles et SQL', 'Niveau lycée. Modéliser des données (entité-association), normaliser, interroger avec SQL (jointures, agrégats, sous-requêtes). Maîtrisé quand l''élève conçoit un schéma relationnel cohérent pour une application réelle et écrit des requêtes SQL multi-tables correctes.', 'savoir-faire', 11, false, 'etabli', NULL, 0.95, '{}', 174),
('40000000-0000-4000-8000-000000000008', 'info-9', 'Réseaux, Internet et Web', 'Niveau lycée. Comprendre modèle en couches, IP/TCP, DNS, HTTP, routage, et développer une page web dynamique client-serveur. Maîtrisé quand l''élève explique le trajet d''une requête du navigateur au serveur et construit une petite application web full-stack fonctionnelle.', 'savoir-faire', 12, false, 'etabli', NULL, 0.95, '{}', 184),
('40000000-0000-4000-8000-000000000009', 'info-10', 'Programmation orientée objet', 'Niveau licence L3. Maîtriser classes, encapsulation, héritage, polymorphisme, interfaces, et principes de conception (SOLID, patrons de conception courants). Maîtrisé quand l''étudiant conçoit une architecture objet extensible pour un système complexe en appliquant les patrons pertinents à bon escient.', 'savoir-faire', 13, false, 'etabli', NULL, 0.95, '{}', 194),
('40000000-0000-4000-8000-000000000010', 'info-11', 'Algorithmique avancée et complexité', 'Niveau licence L3. Analyser la complexité (notations O, Theta, Omega), maîtriser programmation dynamique, algorithmes de graphes (Dijkstra, flots), gloutons, et prouver leur correction. Maîtrisé quand l''étudiant conçoit un algorithme efficace pour un problème inédit, démontre sa correction et borne rigoureusement sa complexité.', 'savoir-faire', 14, false, 'etabli', NULL, 0.95, '{}', 204),
('40000000-0000-4000-8000-000000000011', 'info-12', 'Théorie des langages et automates', 'Niveau licence L3. Manipuler expressions régulières, automates finis, grammaires non contextuelles, automates à pile ; construire analyseurs lexicaux et syntaxiques. Maîtrisé quand l''étudiant définit une grammaire pour un langage donné et construit l''automate ou l''analyseur qui le reconnaît.', 'savoir-faire', 15, false, 'etabli', NULL, 0.95, '{}', 214),
('40000000-0000-4000-8000-000000000012', 'info-13', 'Calculabilité et décidabilité', 'Niveau licence L3. Comprendre machines de Turing, thèse de Church-Turing, indécidabilité (problème de l''arrêt), réductions. Maîtrisé quand l''étudiant prouve l''indécidabilité d''un problème par réduction depuis un problème connu et situe un problème dans la hiérarchie de calculabilité.', 'savoir-faire', 16, false, 'etabli', NULL, 0.95, '{}', 224),
('40000000-0000-4000-8000-000000000013', 'info-14', 'Architecture des ordinateurs', 'Niveau licence L3. Comprendre logique séquentielle, jeu d''instructions, pipeline, hiérarchie mémoire et caches, assembleur. Maîtrisé quand l''étudiant explique le cheminement d''une instruction dans le processeur et optimise un code au regard du cache et du pipeline.', 'savoir-faire', 17, false, 'etabli', NULL, 0.95, '{}', 234),
('40000000-0000-4000-8000-000000000014', 'info-15', 'Systèmes d''exploitation', 'Niveau licence L3. Maîtriser processus, threads, ordonnancement, synchronisation, mémoire virtuelle, systèmes de fichiers, interblocages. Maîtrisé quand l''étudiant implémente une solution correcte à un problème de concurrence (verrous, sémaphores) sans famine ni interblocage et l''argumente.', 'savoir-faire', 18, false, 'etabli', NULL, 0.95, '{}', 244),
('40000000-0000-4000-8000-000000000015', 'info-16', 'Machine learning : fondations', 'Niveau master M2. Maîtriser apprentissage supervisé/non supervisé, régression, arbres, SVM, compromis biais-variance, régularisation, validation croisée, métriques. Maîtrisé quand l''étudiant construit un pipeline ML complet sur données réelles, diagnostique sur/sous-apprentissage et justifie chaque choix méthodologique.', 'savoir-faire', 19, false, 'etabli', NULL, 0.95, '{}', 254),
('40000000-0000-4000-8000-000000000016', 'info-17', 'Deep learning et réseaux de neurones', 'Niveau master M2. Comprendre rétropropagation, descente de gradient stochastique, CNN, RNN/LSTM, régularisation, optimiseurs, et entraîner des modèles profonds. Maîtrisé quand l''étudiant conçoit, entraîne et débogue une architecture profonde atteignant des performances compétitives sur une tâche vision ou séquence.', 'savoir-faire', 20, false, 'etabli', NULL, 0.95, '{}', 264),
('40000000-0000-4000-8000-000000000017', 'info-18', 'Compilation', 'Niveau master M2. Construire un compilateur complet : analyse lexicale/syntaxique/sémantique, représentation intermédiaire, génération et optimisation de code. Maîtrisé quand l''étudiant implémente un compilateur pour un langage jouet produisant du code exécutable correct avec au moins une optimisation.', 'savoir-faire', 21, false, 'etabli', NULL, 0.95, '{}', 274),
('40000000-0000-4000-8000-000000000018', 'info-19', 'Systèmes distribués', 'Niveau master M2. Maîtriser consensus (Paxos/Raft), cohérence, tolérance aux pannes, théorème CAP, horloges logiques, réplication. Maîtrisé quand l''étudiant conçoit un système distribué tolérant aux pannes et raisonne correctement sur ses garanties de cohérence et de disponibilité.', 'savoir-faire', 22, false, 'etabli', NULL, 0.95, '{}', 284),
('40000000-0000-4000-8000-000000000019', 'info-20', 'Sécurité informatique et cryptographie', 'Niveau master M2. Comprendre chiffrement symétrique/asymétrique, protocoles, vulnérabilités (injection, débordement, XSS), modèles de menace, défense. Maîtrisé quand l''étudiant conduit une analyse de menace d''un système, exploite et corrige des vulnérabilités réelles en environnement contrôlé.', 'savoir-faire', 23, false, 'etabli', NULL, 0.95, '{}', 294),
('40000000-0000-4000-8000-000000000020', 'info-21', 'Bases de données avancées et big data', 'Niveau master M2. Maîtriser transactions ACID, indexation, optimisation de requêtes, systèmes NoSQL, traitement distribué (MapReduce, Spark). Maîtrisé quand l''étudiant conçoit et dimensionne un système de données à grande échelle en arbitrant entre modèles relationnels, NoSQL et distribués.', 'savoir-faire', 24, false, 'etabli', NULL, 0.95, '{}', 304),
('40000000-0000-4000-8000-000000000021', 'info-22', 'Architectures Transformer et grands modèles de langage', 'Niveau doctorat. Maîtriser attention, self-attention multi-têtes, positionnement, pré-entraînement, lois d''échelle, fine-tuning, RLHF, et l''implémentation de LLM. Maîtrisé quand le chercheur implémente un Transformer de zéro, analyse ses mécanismes internes et propose une modification architecturale évaluée rigoureusement.', 'savoir-faire', 25, false, 'etabli', NULL, 0.95, '{}', 314),
('40000000-0000-4000-8000-000000000022', 'info-23', 'Apprentissage par renforcement avancé', 'Niveau doctorat. Maîtriser MDP, Q-learning profond, méthodes policy-gradient (PPO, actor-critic), exploration, RL multi-agent et hors-ligne. Maîtrisé quand le chercheur formule un problème complexe en RL, conçoit et entraîne un agent surpassant les baselines de référence et analyse sa convergence.', 'savoir-faire', 26, false, 'etabli', NULL, 0.95, '{}', 324),
('40000000-0000-4000-8000-000000000023', 'info-24', 'Théorie de l''apprentissage statistique', 'Niveau doctorat. Maîtriser dimension VC, bornes de généralisation, PAC-learning, complexité de Rademacher, théorie de l''optimisation non convexe des réseaux profonds. Maîtrisé quand le chercheur démontre une borne de généralisation pour une classe d''hypothèses et relie théorie et comportement empirique observé.', 'savoir-faire', 27, false, 'etabli', NULL, 0.95, '{}', 334),
('40000000-0000-4000-8000-000000000024', 'info-25', 'IA générative de pointe', 'Niveau doctorat. Maîtriser modèles de diffusion, VAE, GAN, autoregressifs, flux normalisants, génération multimodale et leurs fondements probabilistes. Maîtrisé quand le chercheur conçoit un modèle génératif original, l''évalue avec des métriques adaptées et le compare à l''état de l''art de manière défendable.', 'savoir-faire', 28, false, 'etabli', NULL, 0.95, '{}', 344),
('40000000-0000-4000-8000-000000000025', 'info-26', 'Alignement, sûreté et interprétabilité de l''IA', 'Niveau doctorat. Maîtriser interprétabilité mécaniste, alignement des LLM, robustesse adversariale, mise à l''échelle de la supervision, évaluation des risques. Maîtrisé quand le chercheur identifie un mode de défaillance d''alignement, propose une méthode d''atténuation et en démontre empiriquement l''efficacité.', 'savoir-faire', 29, false, 'etabli', NULL, 0.95, '{}', 354),
('40000000-0000-4000-8000-000000000026', 'info-27', 'Recherche et contribution à l''état de l''art en IA', 'Niveau doctorat et au-delà. Formuler une question de recherche originale, concevoir un protocole expérimental rigoureux, produire des résultats reproductibles et rédiger un article. Maîtrisé quand le chercheur publie une contribution acceptée dans une conférence de premier plan (NeurIPS, ICML, ICLR) évaluée par les pairs.', 'savoir-faire', 30, false, 'etabli', NULL, 0.95, '{}', 364),
('50000000-0000-4000-8000-000000000000', 'svt-1', 'Observer et classer le vivant', 'Niveau collège. Distinguer vivant/non-vivant, identifier les caractères communs des êtres vivants, classer plantes/animaux/champignons à partir d''observations et de clés simples. Maîtrisé quand l''élève construit une clé dichotomique fonctionnelle et classe 10 organismes inconnus en justifiant chaque critère.', 'savoir-faire', 4, false, 'etabli', NULL, 0.95, '{}', 105),
('50000000-0000-4000-8000-000000000001', 'svt-2', 'La cellule, unité du vivant', 'Niveau collège. Utiliser un microscope, réaliser une préparation, reconnaître membrane, cytoplasme, noyau, distinguer cellule animale et végétale. Maîtrisé quand l''élève produit un dessin d''observation légendé à l''échelle et explique que tout être vivant est constitué de cellules.', 'savoir-faire', 5, false, 'etabli', NULL, 0.95, '{}', 115),
('50000000-0000-4000-8000-000000000002', 'svt-3', 'Nutrition et organisation du corps humain', 'Niveau collège. Relier digestion, respiration et circulation à l''approvisionnement des organes en nutriments et dioxygène ; schématiser les grands appareils. Maîtrisé quand l''élève trace le trajet complet d''un nutriment et du dioxygène jusqu''à une cellule musculaire en nommant organes et échanges.', 'savoir-faire', 6, false, 'etabli', NULL, 0.95, '{}', 125),
('50000000-0000-4000-8000-000000000003', 'svt-4', 'Reproduction et transmission de la vie', 'Niveau collège. Décrire reproductions sexuée et asexuée, fécondation, puberté et rôle des cellules reproductrices chez l''humain, l''animal et la plante à fleurs. Maîtrisé quand l''élève explique la continuité des espèces via cellules reproductrices et fécondation, et distingue caractères héréditaires et acquis.', 'savoir-faire', 7, false, 'etabli', NULL, 0.95, '{}', 135),
('50000000-0000-4000-8000-000000000004', 'svt-5', 'Écosystèmes et réseaux trophiques', 'Niveau collège. Analyser relations alimentaires (producteurs, consommateurs, décomposeurs), construire chaînes et réseaux, comprendre le recyclage de la matière et l''impact d''une perturbation. Maîtrisé quand l''élève prédit les effets en cascade de la disparition d''une espèce dans un réseau trophique donné.', 'savoir-faire', 8, false, 'etabli', NULL, 0.95, '{}', 145),
('50000000-0000-4000-8000-000000000005', 'svt-6', 'Génétique mendélienne et transmission des allèles', 'Niveau lycée Tle. Poser gène/allèle/génotype/phénotype, résoudre monohybridisme et dihybridisme, échiquier de croisement, dominance/récessivité, hérédité liée au sexe et arbres généalogiques. Maîtrisé quand l''élève résout un croisement dihybride avec test du khi-deux et interprète un pedigree pour établir le mode de transmission d''une maladie.', 'savoir-faire', 9, false, 'etabli', NULL, 0.95, '{}', 155),
('50000000-0000-4000-8000-000000000006', 'svt-7', 'Méiose, brassage et diversité génétique', 'Niveau lycée Tle. Décrire méiose et fécondation, brassages inter- et intrachromosomique, crossing-over, et relier ces mécanismes à la diversité des gamètes. Maîtrisé quand l''élève calcule le nombre de gamètes différents produits et explique une anomalie chromosomique par une erreur de méiose.', 'savoir-faire', 10, false, 'etabli', NULL, 0.95, '{}', 165),
('50000000-0000-4000-8000-000000000007', 'svt-8', 'Mécanismes de l''évolution', 'Niveau lycée Tle. Articuler sélection naturelle, dérive génétique, mutation et spéciation ; interpréter arbres phylogénétiques et preuves (fossiles, homologies, données moléculaires). Maîtrisé quand l''élève reconstruit une phylogénie à partir de caractères dérivés partagés et argumente un scénario évolutif avec des preuves convergentes.', 'savoir-faire', 11, false, 'etabli', NULL, 0.95, '{}', 175),
('50000000-0000-4000-8000-000000000008', 'svt-9', 'Physiologie intégrée et régulation', 'Niveau lycée Tle. Comprendre l''homéostasie par boucles de régulation nerveuse et hormonale (glycémie, pression, température), notion de récepteur/effecteur/rétrocontrôle. Maîtrisé quand l''élève modélise une boucle de rétrocontrôle négatif complète et prédit la réponse de l''organisme à une perturbation expérimentale.', 'savoir-faire', 12, false, 'etabli', NULL, 0.95, '{}', 185),
('50000000-0000-4000-8000-000000000009', 'svt-10', 'Immunologie fondamentale', 'Niveau lycée Tle. Distinguer immunités innée et adaptative, rôles des lymphocytes B et T, anticorps, mémoire immunitaire et principe de la vaccination. Maîtrisé quand l''élève retrace la réponse coordonnée à une infection virale primaire puis secondaire et explique l''efficacité d''un rappel vaccinal.', 'savoir-faire', 13, false, 'etabli', NULL, 0.95, '{}', 195),
('50000000-0000-4000-8000-000000000010', 'svt-11', 'Géologie : Terre, tectonique et temps', 'Niveau lycée Tle. Relier tectonique des plaques, dynamique interne, cycle des roches, datation relative et absolue, lecture des archives géologiques. Maîtrisé quand l''élève interprète une coupe géologique et reconstitue une histoire régionale cohérente.', 'savoir-faire', 14, false, 'etabli', NULL, 0.95, '{}', 205),
('50000000-0000-4000-8000-000000000011', 'svt-12', 'Biologie moléculaire : ADN, réplication et expression', 'Niveau licence L2. Structure des acides nucléiques, réplication semi-conservative, transcription, maturation des ARN, code génétique et traduction ; régulation de l''expression. Maîtrisé quand l''étudiant prédit l''effet d''une mutation ponctuelle ou d''épissage sur la protéine et conçoit un schéma de régulation d''un opéron inductible.', 'savoir-faire', 15, false, 'etabli', NULL, 0.95, '{}', 215),
('50000000-0000-4000-8000-000000000012', 'svt-13', 'Biochimie structurale et métabolisme', 'Niveau licence L2. Structure et fonction des protéines, enzymologie (Michaelis-Menten, inhibitions), voies centrales (glycolyse, cycle de Krebs, phosphorylation oxydative) et bioénergétique. Maîtrisé quand l''étudiant analyse des données cinétiques pour déterminer Km/Vmax et le type d''inhibition, et établit le bilan énergétique d''une voie métabolique.', 'savoir-faire', 16, false, 'etabli', NULL, 0.95, '{}', 225),
('50000000-0000-4000-8000-000000000013', 'svt-14', 'Génétique moléculaire et outils du gène', 'Niveau licence L2. Cartographie, mutations et réparation de l''ADN, recombinaison, clonage, PCR, séquençage Sanger, vecteurs et transgenèse. Maîtrisé quand l''étudiant conçoit une stratégie de clonage complète pour exprimer un gène donné et prévoit les contrôles nécessaires.', 'savoir-faire', 17, false, 'etabli', NULL, 0.95, '{}', 235),
('50000000-0000-4000-8000-000000000014', 'svt-15', 'Physiologie cellulaire et signalisation', 'Niveau licence L2. Transports membranaires, potentiels de membrane, voies de signalisation (récepteurs, seconds messagers, cascades), cycle cellulaire et sa régulation. Maîtrisé quand l''étudiant reconstitue une voie de transduction de la membrane au noyau et prédit les conséquences de l''activation constitutive d''un composant.', 'savoir-faire', 18, false, 'etabli', NULL, 0.95, '{}', 245),
('50000000-0000-4000-8000-000000000015', 'svt-16', 'Microbiologie et diversité microbienne', 'Niveau licence L2. Structure et physiologie bactériennes, croissance et métabolismes, virologie, génétique bactérienne, résistance aux antibiotiques. Maîtrisé quand l''étudiant conçoit un protocole d''isolement/identification d''une souche et explique l''émergence d''une résistance en termes moléculaires et évolutifs.', 'savoir-faire', 19, false, 'etabli', NULL, 0.95, '{}', 255),
('50000000-0000-4000-8000-000000000016', 'svt-17', 'Biologie du développement', 'Niveau master. Mécanismes de l''embryogenèse : axes de polarité, gènes homéotiques, morphogènes, induction, différenciation et cellules souches, apoptose. Maîtrisé quand l''étudiant interprète des phénotypes de mutants et d''expériences de greffe/ablation pour établir la fonction d''un gène régulateur.', 'savoir-faire', 20, false, 'etabli', NULL, 0.95, '{}', 265),
('50000000-0000-4000-8000-000000000017', 'svt-18', 'Génomique et biologie des systèmes', 'Niveau master. Séquençage haut débit (NGS), assemblage et annotation, transcriptomique (RNA-seq), épigénomique, réseaux de régulation ; pipelines bioinformatiques. Maîtrisé quand l''étudiant conçoit et analyse une expérience RNA-seq et interprète les résultats en hypothèses biologiques testables.', 'savoir-faire', 21, false, 'etabli', NULL, 0.95, '{}', 275),
('50000000-0000-4000-8000-000000000018', 'svt-19', 'Neurosciences moléculaires et cellulaires', 'Niveau master. Excitabilité neuronale, transmission synaptique, plasticité (LTP/LTD), circuits et neuromodulation, méthodes électrophysiologiques et d''imagerie. Maîtrisé quand l''étudiant interprète des enregistrements électrophysiologiques et conçoit une expérience discriminant un mécanisme pré- vs post-synaptique.', 'savoir-faire', 22, false, 'etabli', NULL, 0.95, '{}', 285),
('50000000-0000-4000-8000-000000000019', 'svt-20', 'Biologie structurale', 'Niveau master. Détermination de structures (cristallographie RX, RMN, cryo-EM), relations structure-fonction, dynamique et repliement, docking et prédiction (AlphaFold). Maîtrisé quand l''étudiant évalue la qualité d''un modèle structural et formule des hypothèses mécanistiques testables sur un site actif.', 'savoir-faire', 23, false, 'etabli', NULL, 0.95, '{}', 295),
('50000000-0000-4000-8000-000000000020', 'svt-21', 'Biotechnologies et ingénierie du vivant', 'Niveau master. Production de protéines recombinantes, ingénierie métabolique, anticorps thérapeutiques, biologie synthétique, bioprocédés et enjeux réglementaires. Maîtrisé quand l''étudiant conçoit une voie de biosynthèse hétérologue optimisée et argumente sa faisabilité et son cadre éthique.', 'savoir-faire', 24, false, 'etabli', NULL, 0.95, '{}', 305),
('50000000-0000-4000-8000-000000000021', 'svt-22', 'Édition du génome CRISPR avancée', 'Niveau doctorat. Maîtriser CRISPR-Cas de nouvelle génération (base/prime editing, CRISPRi/a, criblage génome), minimiser off-targets, valider par séquençage, concevoir des modèles cellulaires/animaux. Maîtrisé quand le chercheur conçoit et valide une stratégie d''édition originale, quantifie efficacité et effets hors-cible, et publie dans une revue à comité de lecture.', 'savoir-faire', 25, false, 'etabli', NULL, 0.95, '{}', 315),
('50000000-0000-4000-8000-000000000022', 'svt-23', 'Recherche en biologie moléculaire de pointe', 'Niveau doctorat. Concevoir un programme de recherche autonome (structure-fonction, régulation, single-cell, interactomes), maîtriser méthodes émergentes et statistiques rigoureuses. Maîtrisé quand le chercheur formule une hypothèse originale, la teste par une combinaison de techniques convergentes et défend ses conclusions face à la revue par les pairs.', 'savoir-faire', 26, false, 'etabli', NULL, 0.95, '{}', 325),
('50000000-0000-4000-8000-000000000023', 'svt-24', 'Neurosciences computationnelles et modélisation', 'Niveau doctorat. Modéliser neurones et réseaux (Hodgkin-Huxley, populations, codage neuronal), analyser données à grande échelle, intégrer apprentissage automatique et théorie. Maîtrisé quand le chercheur développe un modèle prédictif d''un phénomène neuronal, le valide sur données réelles et en publie l''analyse.', 'savoir-faire', 27, false, 'etabli', NULL, 0.95, '{}', 335),
('50000000-0000-4000-8000-000000000024', 'svt-25', 'Direction de recherche et frontières du vivant', 'Niveau doctorat et au-delà. Piloter un programme original aux frontières (origines de la vie, biologie synthétique de novo, thérapies géniques de rupture), obtenir des financements, encadrer, faire avancer un champ. Maîtrisé quand le chercheur ouvre une question nouvelle reconnue, forme des chercheurs et publie des travaux qui redéfinissent l''état de l''art.', 'savoir-faire', 28, false, 'etabli', NULL, 0.95, '{}', 345),
('60000000-0000-4000-8000-000000000000', 'philo-1', 'Questionner et problématiser : entrer en philosophie', 'Niveau lycée Tle. Transformer un sujet ou une situation ordinaire en problème philosophique : repérer l''implicite, formuler une question, exposer un enjeu. Maîtrisé quand l''élève dégage seul une problématique tenue à partir d''un énoncé banal, sans réponse toute faite.', 'savoir-faire', 4, false, 'etabli', NULL, 0.95, '{}', 106),
('60000000-0000-4000-8000-000000000001', 'philo-2', 'Distinguer opinion, croyance et argument', 'Niveau lycée Tle. Séparer ce qui relève du sentiment personnel, du préjugé et de l''argument justifié ; identifier prémisses et conclusion dans un propos. Maîtrisé quand l''élève reformule une thèse adverse fidèlement et distingue sa validité de son caractère plaisant ou partagé.', 'savoir-faire', 5, false, 'etabli', NULL, 0.95, '{}', 116),
('60000000-0000-4000-8000-000000000002', 'philo-3', 'Conscience, sujet et identité personnelle', 'Niveau lycée Tle. Mobiliser la notion de conscience (de soi, morale, inconscient) pour analyser un cas ; connaître une position classique et son objection. Maîtrisé quand l''élève articule une thèse (Descartes, Freud) à un exemple précis et en montre la limite.', 'savoir-faire', 6, false, 'etabli', NULL, 0.95, '{}', 126),
('60000000-0000-4000-8000-000000000003', 'philo-4', 'Liberté, déterminisme et responsabilité', 'Niveau lycée Tle. Poser le conflit entre déterminisme et libre arbitre, et ses conséquences sur la responsabilité morale. Maîtrisé quand l''élève construit un dilemme argumenté opposant au moins deux positions et en tire une conséquence pratique cohérente.', 'savoir-faire', 7, false, 'etabli', NULL, 0.95, '{}', 136),
('60000000-0000-4000-8000-000000000004', 'philo-5', 'Justice, droit et légitimité', 'Niveau lycée Tle. Distinguer légalité et légitimité, justice commutative et distributive ; discuter une conception de l''égalité. Maîtrisé quand l''élève applique une distinction conceptuelle à un cas politique réel et défend une position en anticipant l''objection.', 'savoir-faire', 8, false, 'etabli', NULL, 0.95, '{}', 146),
('60000000-0000-4000-8000-000000000005', 'philo-6', 'Vérité, savoir et illusion', 'Niveau lycée Tle. Distinguer vérité, certitude et vraisemblance ; problématiser les critères du vrai et le rôle du doute. Maîtrisé quand l''élève analyse un exemple d''erreur ou d''illusion en mobilisant une théorie de la vérité et ses présupposés.', 'savoir-faire', 9, false, 'etabli', NULL, 0.95, '{}', 156),
('60000000-0000-4000-8000-000000000006', 'philo-7', 'Méthode de la dissertation philosophique', 'Niveau lycée Tle. Analyser un sujet, problématiser, construire un plan dialectique progressif, rédiger transitions et conclusion. Maîtrisé quand l''élève produit une dissertation complète où chaque partie répond à un moment distinct du problème, sans juxtaposition d''opinions.', 'savoir-faire', 10, false, 'etabli', NULL, 0.95, '{}', 166),
('60000000-0000-4000-8000-000000000007', 'philo-8', 'Explication de texte philosophique', 'Niveau lycée Tle. Dégager thèse, structure argumentative et enjeux d''un extrait ; expliquer les concepts sans paraphrase. Maîtrisé quand l''élève restitue le mouvement d''un texte et en éclaire un passage difficile par une reconstruction fidèle de l''argument.', 'savoir-faire', 11, false, 'etabli', NULL, 0.95, '{}', 176),
('60000000-0000-4000-8000-000000000008', 'philo-9', 'Logique formelle et théorie de l''argumentation', 'Niveau licence L2. Maîtriser calcul propositionnel et des prédicats, validité, tables de vérité, sophismes et schémas argumentatifs. Maîtrisé quand l''étudiant formalise un raisonnement en langue naturelle, teste sa validité et diagnostique le type précis de faute logique.', 'savoir-faire', 12, false, 'etabli', NULL, 0.95, '{}', 186),
('60000000-0000-4000-8000-000000000009', 'philo-10', 'Épistémologie : nature et limites de la connaissance', 'Niveau licence L2. Discuter analyse tripartite du savoir, problème de Gettier, justification, scepticisme, induction et démarcation scientifique. Maîtrisé quand l''étudiant reconstruit un débat épistémologique et évalue les réponses aux contre-exemples classiques.', 'savoir-faire', 13, false, 'etabli', NULL, 0.95, '{}', 196),
('60000000-0000-4000-8000-000000000010', 'philo-11', 'Métaphysique : être, cause, modalité', 'Niveau licence L2. Traiter des questions d''existence, d''universaux, de causalité, de nécessité et contingence, d''identité et persistance. Maîtrisé quand l''étudiant expose une position métaphysique argumentée sur un problème précis en pesant ses coûts théoriques.', 'savoir-faire', 14, false, 'etabli', NULL, 0.95, '{}', 206),
('60000000-0000-4000-8000-000000000011', 'philo-12', 'Philosophie morale : les grandes théories normatives', 'Niveau licence L2. Comparer conséquentialisme, déontologie kantienne et éthique des vertus sur des cas ; distinguer méta-éthique et éthique normative. Maîtrisé quand l''étudiant applique rigoureusement deux cadres à un dilemme et en tire des verdicts contrastés justifiés.', 'savoir-faire', 15, false, 'etabli', NULL, 0.95, '{}', 216),
('60000000-0000-4000-8000-000000000012', 'philo-13', 'Philosophie politique : légitimité et pouvoir', 'Niveau licence L2. Analyser contrat social, souveraineté, liberté, égalité et justice sociale de Hobbes à Rawls. Maîtrisé quand l''étudiant reconstruit une théorie de la justice et la confronte à une objection majeure (Nozick, communautariens) avec précision.', 'savoir-faire', 16, false, 'etabli', NULL, 0.95, '{}', 226),
('60000000-0000-4000-8000-000000000013', 'philo-14', 'Histoire de la philosophie : de Platon à Kant', 'Niveau licence L2. Situer et articuler les grands systèmes (Platon, Aristote, rationalisme, empirisme, criticisme kantien) dans leur logique interne. Maîtrisé quand l''étudiant explique une rupture conceptuelle majeure en la reliant aux textes sources, sans anachronisme.', 'savoir-faire', 17, false, 'etabli', NULL, 0.95, '{}', 236),
('60000000-0000-4000-8000-000000000014', 'philo-15', 'Phénoménologie et philosophies de l''existence', 'Niveau licence L2. Comprendre intentionnalité, réduction, corps propre, être-au-monde chez Husserl, Heidegger, Merleau-Ponty, Sartre. Maîtrisé quand l''étudiant applique une analyse phénoménologique à une expérience concrète en respectant la méthode descriptive.', 'savoir-faire', 18, false, 'etabli', NULL, 0.95, '{}', 246),
('60000000-0000-4000-8000-000000000015', 'philo-16', 'Philosophie analytique : méthode et débats', 'Niveau master. Maîtriser l''analyse conceptuelle, les expériences de pensée, la clarté argumentative et les grands débats analytiques contemporains. Maîtrisé quand l''étudiant construit un argument analytique serré, anticipe les contre-exemples et révise sa thèse en conséquence.', 'savoir-faire', 19, false, 'etabli', NULL, 0.95, '{}', 256),
('60000000-0000-4000-8000-000000000016', 'philo-17', 'Philosophie du langage : sens et référence', 'Niveau master. Traiter sens/référence, descriptions, noms propres, actes de langage, holisme et théories de la signification (Frege à Kripke). Maîtrisé quand l''étudiant évalue une théorie de la référence face à ses cas problématiques et en défend une version amendée.', 'savoir-faire', 20, false, 'etabli', NULL, 0.95, '{}', 266),
('60000000-0000-4000-8000-000000000017', 'philo-18', 'Philosophie de l''esprit et conscience', 'Niveau master. Discuter dualisme, physicalisme, fonctionnalisme, qualia, intentionnalité et problème difficile de la conscience. Maîtrisé quand l''étudiant articule un argument (zombie, connaissance, multi-réalisabilité) et en évalue la portée contre les réponses réductionnistes.', 'savoir-faire', 21, false, 'etabli', NULL, 0.95, '{}', 276),
('60000000-0000-4000-8000-000000000018', 'philo-19', 'Éthique appliquée et philosophie pratique', 'Niveau master. Conduire une analyse rigoureuse en bioéthique, éthique environnementale, technologique ou animale, articulant principes et cas. Maîtrisé quand l''étudiant produit une argumentation normative nuancée sur un cas controversé, traçable jusqu''à ses prémisses théoriques.', 'savoir-faire', 22, false, 'etabli', NULL, 0.95, '{}', 286),
('60000000-0000-4000-8000-000000000019', 'philo-20', 'Méthodologie de la recherche philosophique', 'Niveau master. Construire une problématique de recherche, un état de l''art critique, un appareil de références et une stratégie argumentative. Maîtrisé quand l''étudiant rédige un mémoire dont la thèse originale s''insère précisément dans un débat identifié et documenté.', 'savoir-faire', 23, false, 'etabli', NULL, 0.95, '{}', 296),
('60000000-0000-4000-8000-000000000020', 'philo-21', 'Herméneutique et exégèse de textes difficiles', 'Niveau doctorat. Interpréter des corpus complexes ou anciens en maîtrisant contexte, traductions, tradition critique et cercle herméneutique. Maîtrisé quand le chercheur produit une lecture inédite et défendable d''un texte, discutée face aux interprétations autorisées existantes.', 'savoir-faire', 24, false, 'etabli', NULL, 0.95, '{}', 306),
('60000000-0000-4000-8000-000000000021', 'philo-22', 'Argumentation de pointe et contribution originale', 'Niveau doctorat. Élaborer une thèse philosophique nouvelle : objection inédite, distinction, ou position dans un débat contemporain vivant. Maîtrisé quand le chercheur défend un argument original résistant à l''examen des spécialistes et fait progresser la discussion.', 'savoir-faire', 25, false, 'etabli', NULL, 0.95, '{}', 316),
('60000000-0000-4000-8000-000000000022', 'philo-23', 'Produire une thèse philosophique publiable', 'Niveau doctorat. Conduire une recherche doctorale longue : cohérence systématique, dialogue avec la littérature de pointe, rigueur et fécondité. Maîtrisé quand le travail est jugé apte à publication par des pairs et reconnu comme contribution à son champ.', 'savoir-faire', 26, false, 'etabli', NULL, 0.95, '{}', 326),
('60000000-0000-4000-8000-000000000023', 'philo-24', 'Diriger un débat et un programme de recherche', 'Niveau doctorat. Ouvrir un problème, fédérer un champ, arbitrer des controverses et former d''autres chercheurs au-delà de la thèse. Maîtrisé quand les travaux du chercheur sont cités comme référence structurante et reconfigurent la manière dont une question est posée.', 'savoir-faire', 27, false, 'etabli', NULL, 0.95, '{}', 336)
insert into public.prerequisites (skill_id, prerequisite_id)
values
('10000000-0000-4000-8000-000000000000', '00000000-0000-4000-8000-000000000302'),
('10000000-0000-4000-8000-000000000001', '10000000-0000-4000-8000-000000000000'),
